cat > ./local/roam-playwright/key-image-query.mjs <<'EOF'
export default {
  async run({ page }) {
    return page.evaluate(async () => {
      const api = window.roamAlphaAPI;
      const pull = (uid) =>
        api.pull(
          "[:block/uid :block/string :block/order :block/heading {:block/children ...}]",
          [":block/uid", uid],
        );
      const simplify = (n) =>
        n
          ? {
              uid: n[":block/uid"],
              text: n[":block/string"] || "",
              children: (n[":block/children"] || [])
                .sort((a, b) => (a[":block/order"] ?? 0) - (b[":block/order"] ?? 0))
                .map(simplify),
            }
          : null;
      const queryUid = "nFs49MWEn";
      const queryTree = simplify(pull(queryUid));
      let rawResults = null;
      let rawError = null;
      try {
        rawResults = (
          await window.roamjs.extension.queryBuilder.runQuery(queryUid)
        )
          .slice(0, 5)
          .map((r) => ({ uid: r.uid, text: String(r.text).slice(0, 80) }));
      } catch (e) {
        rawError = String(e);
      }
      return { queryTree, rawResults, rawError };
    });
  },
};
EOF
