const TITLE = `dg-eng1356-timing-${Date.now()}`;
export default {
  async run({ page }) {
    return page.evaluate(async (title) => {
      const api = window.roamAlphaAPI;
      const gen = () => api.util.generateUID();
      const pageUid = gen(); const h1Uid = gen(); const childUid = gen();
      await api.data.page.create({ page: { title, uid: pageUid } });
      await api.data.block.create({ location: { "parent-uid": pageUid, order: 0 }, block: { uid: h1Uid, string: "Key Image", heading: 1 } });
      await api.data.block.create({ location: { "parent-uid": h1Uid, order: 0 }, block: { uid: childUid, string: "" } });
      const dl = `[:find ?uid :in $ ?title :where [?p :node/title ?title] [?h1 :block/page ?p] [?h1 :block/heading 1] [?node :block/parents ?h1] [?node :block/uid ?uid]]`;
      const t0 = performance.now();
      const local = await api.data.async.fast.q(dl, title);
      const backend0 = await api.data.backend.q(dl, title);
      const t1 = performance.now();
      await new Promise((r) => setTimeout(r, 3000));
      const backend3s = await api.data.backend.q(dl, title);
      return { title, pageUid, childUid, local: local.flat(), backendImmediate: backend0.flat(), backendAfter3s: backend3s.flat(), backendImmediateMs: Math.round(t1 - t0) };
    }, TITLE);
  },
  async cleanup({ page, state }) {
    if (!state?.pageUid) return "nothing to clean";
    return page.evaluate(async (uid) => { await window.roamAlphaAPI.data.page.delete({ page: { uid } }); return `deleted ${uid}`; }, state.pageUid);
  },
};
EOF
